/**
 * The Singapore-region "data transmission" map — the centerpiece visual of the
 * Singapore VPS hero. A stylized digital map (grid + faint particle field, not
 * a literal geographic silhouette) with a glowing Singapore node sending
 * curved gradient trails out to APAC city nodes, each labeled with a
 * presentational latency figure.
 *
 * Motion (see the `.sg-*` rules in app/globals.css for the actual keyframes):
 *  1. `.sg-trail` — every trail's stroke-dashoffset loops continuously, so the
 *     line itself reads as "flowing" outward from Singapore. Pure CSS,
 *     supported everywhere.
 *  2. `.sg-particle` — a small glowing dot rides the exact same curve via CSS
 *     motion-path (`offset-path` + `offset-distance`), progressively
 *     enhanced behind `@supports` on top of (1).
 *  3. `.sg-node-ring` — a soft expanding/fading ring pulses behind the
 *     Singapore node.
 * All three are frozen (not hidden) under `prefers-reduced-motion: reduce`.
 *
 * Deterministic by construction (no Math.random() at render time) so the
 * server-rendered markup matches the client on hydration.
 */

const VB_W = 640;
const VB_H = 520;

const SINGAPORE = { x: 335, y: 300 };

type City = {
  name: string;
  cc: string;
  ms: number;
  x: number;
  y: number;
  /** Quadratic bezier control point for the trail from Singapore to this city. */
  cx: number;
  cy: number;
  /** Which side of the node the label pill sits on, so it never overlaps the trail. */
  labelSide: "top" | "bottom" | "left" | "right";
};

// Positions are stylized, not to scale — but each city sits in roughly the
// correct compass direction from Singapore: Malaysia/Indonesia immediately
// north/south, Thailand/Vietnam nearby north, India far northwest, Japan far
// northeast, Australia far southeast.
const CITIES: City[] = [
  { name: "Malaysia", cc: "my", ms: 18, x: 313, y: 231, cx: 291, cy: 262, labelSide: "left" },
  { name: "Indonesia", cc: "id", ms: 28, x: 300, y: 388, cx: 271, cy: 347, labelSide: "bottom" },
  { name: "Thailand", cc: "th", ms: 20, x: 213, y: 193, cx: 200, cy: 254, labelSide: "top" },
  { name: "Vietnam", cc: "vn", ms: 22, x: 412, y: 172, cx: 432, cy: 249, labelSide: "top" },
  { name: "India", cc: "in", ms: 38, x: 92, y: 203, cx: 142, cy: 268, labelSide: "left" },
  { name: "Japan", cc: "jp", ms: 52, x: 556, y: 68, cx: 562, cy: 188, labelSide: "top" },
  { name: "Australia", cc: "au", ms: 48, x: 492, y: 472, cx: 472, cy: 408, labelSide: "bottom" },
];

// Deterministic pseudo-random particle field (mulberry32) — same output on
// every render, server and client alike, so hydration never mismatches.
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rand = mulberry32(20260826);
const DOTS = Array.from({ length: 46 }, () => ({
  x: rand() * VB_W,
  y: rand() * VB_H,
  r: 0.6 + rand() * 1.3,
  o: 0.08 + rand() * 0.22,
}));

function pathFor(city: City) {
  return `M${SINGAPORE.x},${SINGAPORE.y} Q${city.cx},${city.cy} ${city.x},${city.y}`;
}

const labelOffset: Record<City["labelSide"], { dx: string; dy: string }> = {
  top: { dx: "-50%", dy: "calc(-100% - 12px)" },
  bottom: { dx: "-50%", dy: "12px" },
  left: { dx: "calc(-100% - 12px)", dy: "-50%" },
  right: { dx: "12px", dy: "-50%" },
};

export function SingaporeLatencyMap() {
  return (
    <div
      className="relative aspect-[4/3] w-full overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-950"
      role="img"
      aria-label="Map of Singapore sending live low-latency connections out to Thailand (20ms), Japan (52ms), India (38ms), Vietnam (22ms), Malaysia (18ms), Indonesia (28ms), and Australia (48ms)"
    >
      {/* Ambient depth glow behind the whole panel */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            "radial-gradient(ellipse 60% 55% at 52% 55%, rgb(111 71 245 / 0.16), transparent 70%), radial-gradient(ellipse 40% 35% at 15% 10%, rgb(59 130 246 / 0.10), transparent 70%)",
        }}
      />

      <svg
        viewBox={`0 0 ${VB_W} ${VB_H}`}
        className="absolute inset-0 h-full w-full"
        preserveAspectRatio="xMidYMid slice"
        aria-hidden
      >
        <defs>
          <pattern id="sg-grid" width="32" height="32" patternUnits="userSpaceOnUse">
            <path d="M32 0 H0 V32" fill="none" stroke="white" strokeOpacity="0.05" strokeWidth="1" />
          </pattern>
          <linearGradient id="sg-trail-grad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="var(--color-accent-blue)" stopOpacity="0.9" />
            <stop offset="100%" stopColor="var(--color-brand-500)" stopOpacity="0.15" />
          </linearGradient>
          <radialGradient id="sg-node-glow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#eaf2ff" stopOpacity="1" />
            <stop offset="35%" stopColor="var(--color-accent-blue)" stopOpacity="0.55" />
            <stop offset="100%" stopColor="var(--color-brand-500)" stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* Technical grid */}
        <rect width={VB_W} height={VB_H} fill="url(#sg-grid)" />

        {/* Faint scattered particle field */}
        {DOTS.map((d, i) => (
          <circle key={i} cx={d.x} cy={d.y} r={d.r} fill="#8fb4ff" opacity={d.o} />
        ))}

        {/* Trail lines, Singapore outward to each city */}
        {CITIES.map((city, i) => (
          <path
            key={city.name}
            d={pathFor(city)}
            fill="none"
            stroke="url(#sg-trail-grad)"
            strokeWidth={1.6}
            strokeLinecap="round"
            className="sg-trail"
            style={{ animationDelay: `${-(i * 0.22)}s` }}
          />
        ))}

        {/* City nodes */}
        {CITIES.map((city) => (
          <g key={city.name}>
            <circle cx={city.x} cy={city.y} r={9} fill="url(#sg-node-glow)" opacity={0.9} />
            <circle cx={city.x} cy={city.y} r={2.6} fill="#dbe8ff" />
          </g>
        ))}

        {/* Singapore node — pulsing halo + bright core */}
        <circle
          cx={SINGAPORE.x}
          cy={SINGAPORE.y}
          r={10}
          fill="none"
          stroke="var(--color-accent-blue)"
          strokeWidth={1.5}
          className="sg-node-ring"
        />
        <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r={22} fill="url(#sg-node-glow)" />
        <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r={5} fill="#ffffff" />
      </svg>

      {/* Traveling particles — riding the identical curves via CSS motion-path */}
      {CITIES.map((city, i) => (
        <span
          key={city.name}
          aria-hidden
          className="sg-particle absolute left-0 top-0 h-[6px] w-[6px] rounded-full bg-white shadow-[0_0_8px_2px_rgba(148,180,255,0.9)]"
          style={{
            offsetPath: `path("${pathFor(city)}")`,
            offsetRotate: "0deg",
            animationDelay: `${i * 0.34}s`,
            // Percentage math below converts the shared SVG viewBox to this
            // element's own box so offset-path lines up with the drawn path.
            transform: `translate(${(-3 / VB_W) * 100}%, ${(-3 / VB_H) * 100}%)`,
          }}
        />
      ))}

      {/* City labels */}
      {CITIES.map((city) => {
        const off = labelOffset[city.labelSide];
        return (
          <div
            key={city.name}
            className="absolute flex items-center gap-1.5 rounded-full border border-white/10 bg-navy-950/85 px-2.5 py-1 text-[11px] font-medium text-slate-200 shadow-[0_4px_14px_-6px_rgba(0,0,0,0.6)] backdrop-blur-sm"
            style={{
              left: `${(city.x / VB_W) * 100}%`,
              top: `${(city.y / VB_H) * 100}%`,
              transform: `translate(${off.dx}, ${off.dy})`,
            }}
          >
            <span>{city.name}</span>
            <span className="font-mono text-[10px] font-semibold text-accent-cyan">{city.ms}ms</span>
          </div>
        );
      })}

      {/* Singapore label */}
      <div
        className="absolute flex items-center gap-1.5 rounded-full border border-brand-400/30 bg-navy-950/90 px-3 py-1.5 text-xs font-semibold text-white shadow-[0_6px_18px_-6px_rgba(111,71,245,0.55)]"
        style={{
          left: `${(SINGAPORE.x / VB_W) * 100}%`,
          top: `${(SINGAPORE.y / VB_H) * 100}%`,
          transform: "translate(-50%, calc(-100% - 20px))",
        }}
      >
        <img src="/flags/sg.png" width={14} height={11} alt="" className="rounded-[2px] object-cover" />
        Singapore
      </div>
    </div>
  );
}

