import type { PlanCard } from "@/components/marketing/PricingGrid";

/**
 * The "live server spec" card in the Singapore hero — a dark bordered panel
 * showing the real Standard-plan spec (pulled from the live `Plan` table by
 * the caller, not hardcoded) plus a "your server is live" strip with a
 * genuinely animating deploy progress bar.
 *
 * Progress bar motion is two layered, pre-existing site animations (both
 * defined in app/globals.css, already used elsewhere on the marketing site):
 *  - `animate-grow-x` — one-shot scaleX(0 → 1) fill-in on the gradient bar.
 *  - `animate-sweep` — a continuous soft light sweep across the fill on top,
 *    giving it a shimmering "still working" sheen rather than a static bar.
 * Both are Tailwind `motion-safe:` variants, so prefers-reduced-motion users
 * see the bar at its resting (filled) state with no motion, per site convention.
 */

type Spec = {
  label: string;
  value: string;
  icon: React.ReactNode;
};

const iconCls = "h-4 w-4 text-accent-blue";

function CpuIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <rect x="7" y="7" width="10" height="10" rx="1.5" stroke="currentColor" strokeWidth="1.6" />
      <path
        d="M9 4v2.5M12 4v2.5M15 4v2.5M9 17.5V20M12 17.5V20M15 17.5V20M4 9h2.5M4 12h2.5M4 15h2.5M17.5 9H20M17.5 12H20M17.5 15H20"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}
function MemoryIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <rect x="3.5" y="7" width="17" height="10" rx="1.5" stroke="currentColor" strokeWidth="1.6" />
      <path d="M7 7V4.5M11 7V4.5M15 7V4.5M17 7V4.5M7 17v2.5M11 17v2.5M15 17v2.5M17 17v2.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
    </svg>
  );
}
function StorageIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <ellipse cx="12" cy="6" rx="8" ry="3" stroke="currentColor" strokeWidth="1.6" />
      <path d="M4 6v12c0 1.66 3.58 3 8 3s8-1.34 8-3V6" stroke="currentColor" strokeWidth="1.6" />
      <path d="M4 12c0 1.66 3.58 3 8 3s8-1.34 8-3" stroke="currentColor" strokeWidth="1.6" />
    </svg>
  );
}
function BandwidthIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <path d="M4 17c2.5-6 13.5-6 16 0" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
      <path d="M7 17c1.5-3 8.5-3 10 0" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
      <circle cx="12" cy="17" r="1.4" fill="currentColor" />
    </svg>
  );
}
function IpIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <circle cx="12" cy="12" r="8.25" stroke="currentColor" strokeWidth="1.6" />
      <path d="M3.75 12h16.5M12 3.75c2.2 2.4 3.3 5.2 3.3 8.25S14.2 17.85 12 20.25C9.8 17.85 8.7 15.05 8.7 12S9.8 6.15 12 3.75Z" stroke="currentColor" strokeWidth="1.6" />
    </svg>
  );
}
function UptimeIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <path d="M12 3.5l7.5 3.4v5c0 4.6-3.1 8.4-7.5 9.6-4.4-1.2-7.5-5-7.5-9.6v-5L12 3.5Z" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" />
      <path d="M9 12.2l2.1 2.1L15.3 10" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function formatRam(mb: number) {
  const gb = mb / 1024;
  return `${gb % 1 ? gb.toFixed(1) : gb.toFixed(0)} GB RAM`;
}

export function LiveServerCard({ plan }: { plan: Pick<PlanCard, "cpuCores" | "ramMB" | "diskGB" | "bandwidthTB"> }) {
  const specs: Spec[] = [
    { label: "vCPU", value: `${plan.cpuCores} vCPU`, icon: <CpuIcon /> },
    { label: "Memory", value: formatRam(plan.ramMB), icon: <MemoryIcon /> },
    { label: "Storage", value: `${plan.diskGB} GB NVMe`, icon: <StorageIcon /> },
    { label: "Bandwidth", value: `${plan.bandwidthTB} TB`, icon: <BandwidthIcon /> },
    { label: "IPv4", value: "Dedicated", icon: <IpIcon /> },
    { label: "Uptime", value: "99.9%", icon: <UptimeIcon /> },
  ];

  return (
    <div className="w-full max-w-sm rounded-2xl border border-white/[0.08] bg-navy-900/80 shadow-[0_20px_60px_-24px_rgba(0,0,0,0.65)] backdrop-blur-md">
      {/* Header */}
      <div className="flex items-center justify-between gap-3 border-b border-white/[0.06] px-5 py-4">
        <div className="flex items-center gap-2">
          <img src="/flags/sg.png" width={16} height={12} alt="" className="rounded-[2px] object-cover" />
          <span className="text-sm font-semibold text-white">sgp1 · Singapore</span>
        </div>
        <span className="inline-flex items-center gap-1.5 rounded-full border border-emerald-400/25 bg-emerald-400/10 px-2.5 py-1 text-[11px] font-semibold text-emerald-300">
          <span className="relative flex h-1.5 w-1.5">
            <span className="motion-safe:animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />
            <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-emerald-400" />
          </span>
          Live
        </span>
      </div>

      {/* Spec rows */}
      <div className="space-y-3 px-5 py-4">
        {specs.map((s) => (
          <div key={s.label} className="flex items-center justify-between gap-3 text-sm">
            <span className="flex items-center gap-2.5 text-slate-400">
              <span className="flex h-7 w-7 flex-none items-center justify-center rounded-lg bg-gradient-to-br from-accent-blue/15 to-brand-500/15">
                {s.icon}
              </span>
              {s.label}
            </span>
            <span className="font-semibold text-white">{s.value}</span>
          </div>
        ))}
      </div>

      {/* Deploy status strip */}
      <div className="border-t border-white/[0.06] px-5 py-4">
        <div className="flex items-center justify-between">
          <span className="text-sm font-medium text-white">Your server is live</span>
          <span className="rounded-md bg-white/[0.06] px-2 py-0.5 font-mono text-[11px] text-slate-300">47s</span>
        </div>

        <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-white/[0.07]">
          <div
            className="relative h-full w-[97%] origin-left rounded-full bg-gradient-to-r from-accent-blue to-brand-500 motion-safe:animate-grow-x"
            style={{ animationDuration: "1.4s" }}
          >
            <span className="absolute inset-0 motion-safe:animate-sweep bg-gradient-to-r from-transparent via-white/60 to-transparent" />
          </div>
        </div>

        <div className="mt-2 flex items-center justify-between text-[11px]">
          <span className="flex items-center gap-1.5 text-slate-400">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
            SSH ready
          </span>
          <span className="font-mono font-semibold text-brand-200">100%</span>
        </div>
      </div>
    </div>
  );
}

